'use client';

import * as React from 'react';

// @interlace/data-table v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/data-table
// What changed since: https://ds.interlace.tools/c/data-table#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — DataTable
 *
 * Columns, sorting, row selection, pagination, and the three states a table
 * spends most of its life in (loading / empty / error). It composes
 * primitives — Checkbox, Pagination, Skeleton, Button — so it is a pattern,
 * not a primitive.
 *
 * ## It is a real `<table>`
 *
 * Not a grid of divs. `<caption>` names it, `<th scope="col">` names each
 * column, and one column per row is a `<th scope="row">` that names the row
 * (`rowHeader` on the column, defaulting to the first). That triple is what
 * makes a screen reader announce "Revenue, March, 41,200" instead of
 * "41,200" — a bare number in a bare cell is unreadable by anyone not
 * looking at the screen, and no amount of `aria-label` on the wrapper fixes
 * it. It is the same contract `charts/series-table.tsx` exists to honour for
 * the chart layer.
 *
 * ## State is the caller's
 *
 * `sort` / `onSortChange` and `selected` / `onSelectionChange` are props, not
 * `useState`. The table renders `rows` in the order it received them and
 * highlights the keys it was handed.
 *
 * That is not purity for its own sake — it is the only shape that satisfies
 * URL_PHILOSOPHY / DEEP_LINKING_PHILOSOPHY. Table state belongs in the query
 * string (`?sort=createdAt&dir=desc&page=3`) so a filtered, sorted, paged
 * view survives a refresh and can be pasted to a colleague. A table holding
 * its own sort state cannot put it there, and the "controlled OR uncontrolled"
 * compromise is worse: it makes the URL an optional feature, which means it
 * is the feature nobody wires up. It also means the SORT ITSELF is the
 * caller's — server-side for anything real; `sortRows` from
 * `./data-table-model.js` for the small in-memory case.
 *
 * Selection is keyed by row ID (`rowKey`), never by index, so it survives
 * both sorting and pagination.
 *
 * ## MIN_VIEWPORT — 320
 *
 * The table scrolls horizontally inside its own container; the page never
 * does. The pager and the selection bar sit OUTSIDE that container, so they
 * stay put while the columns scroll under them.
 *
 * | Rule | Concept                    | Where in this file                                            |
 * | ---- | -------------------------- | ------------------------------------------------------------- |
 * | R4   | Extends native el          | `Omit<React.ComponentProps<'div'>, 'onSelect'>`                |
 * | R6   | data-slot on every part    | `data-table` / `-scroll` / `-head` / `-row` / `-pagination`    |
 * | R7   | className merged + ...rest | `cn(...)` + `{...props}`                                       |
 * | R8   | No `isXxx`                 | `loading`, `dense`, `selected`, `sort`                         |
 * | R10  | Composition seam           | `columns[].cell`, `empty`, `error`, `toolbar` take nodes       |
 * | R11  | One variable per part      | the row owns selection; the head owns sort                     |
 * | R12  | Reuse over wrap            | Checkbox / Pagination / Skeleton / Button are the primitives   |
 * | R13  | Ecosystem first            | zero new dependencies — no TanStack Table                      |
 * | R14  | Declares min viewport      | `data-min-viewport={String(MIN_VIEWPORT)}`                     |
 * | R18  | Tailwind only              | zero inline `style`                                            |
 * | R19  | Tokens only                | `border-border`, `bg-muted`, `text-muted-foreground`           |
 * | R20  | AA contrast                | selected row = `bg-accent`/`text-accent-foreground` (9.31:1 light, 9.85:1 dark) |
 * | R23  | No layout shift            | `loading` paints `<Skeleton variant="data-table" />`           |
 * | R25  | Client component           | sort / selection handlers                                      |
 * | R26  | A11y                       | table semantics + `aria-sort` + named checkboxes + live region |
 *
 * ## What this is not
 *
 * No filtering UI, no column resize/reorder, no virtualization, no grouping.
 * Each is named in DATA_TABLE_PHILOSOPHY; each is a separate surface with its
 * own URL contract, and a half-built one is worse than an absent one because
 * it reads as capability. See the notes at the bottom of this file.
 */

import { ArrowDownIcon, ArrowUpIcon, ChevronsUpDownIcon } from 'lucide-react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Pagination,
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
} from '@/components/ui/pagination';
import { Skeleton } from '@/components/ui/skeleton';
import {
  ariaSortOf,
  clampPage,
  columnName,
  nextSort,
  pageSelectionState,
  pageWindow,
  selectionMessage,
  sortActionLabel,
  toggleKey,
  togglePageSelection,
  type DataTableSort,
} from '@/components/ui/patterns/data-table-model';

export const MIN_VIEWPORT = 320 as const;

/**
 * Stable empty array for the `selected` default.
 *
 * A `= []` default literal is a new array on every render, which changes the
 * identity of the memo input below it and turns the memo into a no-op.
 */
const EMPTY_SELECTION: readonly string[] = [];

export interface DataTableColumn<Row> {
  /**
   * Stable identifier AND the sort key. It is what `sort.columnId` carries
   * into `?sort=`, so it should be the server's field name — not the display
   * label, which is free to change.
   */
  id: string;
  /** Header content. Usually a string; may be any node. */
  header: React.ReactNode;
  /** Cell renderer for this column. */
  cell: (row: Row) => React.ReactNode;
  /**
   * Plain-text column name for the strings assistive tech reads (the sort
   * button's action label). Only needed when `header` is not a string.
   */
  name?: string;
  /**
   * Marks the column sortable: the header becomes a real `<button>` and the
   * `<th>` carries `aria-sort`. Requires `onSortChange` to do anything.
   */
  sortable?: boolean;
  /** `end` right-aligns the column — use it for numbers. */
  align?: 'start' | 'end';
  /**
   * Renders this column's cell as `<th scope="row">` — the cell that NAMES
   * the row. Exactly one column should set it; if none does, the first
   * column is used, because a table whose rows have no header announces
   * every value as an orphan.
   */
  rowHeader?: boolean;
  /** Merged onto both the `<th>` and the `<td>` of this column. */
  className?: string;
}

export interface DataTablePaginationState {
  /** 1-based. */
  page: number;
  pageCount: number;
  /**
   * The href for a page. Give a real one — a pager of `href="#"` is a pager
   * you cannot middle-click, bookmark, or hand to a crawler
   * (PAGINATION_PHILOSOPHY).
   */
  href?: (page: number) => string;
  /**
   * Called on activation. When present the click is intercepted
   * (`preventDefault`) so a router can own the navigation; when absent the
   * link navigates on its own.
   */
  onPageChange?: (page: number) => void;
}

export interface DataTableProps<Row>
  extends Omit<React.ComponentProps<'div'>, 'onSelect'> {
  columns: readonly DataTableColumn<Row>[];
  rows: readonly Row[];
  /**
   * Stable identity per row. Selection is keyed by this value, so it must
   * survive sorting, paging and refetching — a database id, not an index.
   */
  rowKey: (row: Row) => string;
  /**
   * The `<caption>`. Required: an unnamed table of numbers is a wall of
   * numbers, and it is the first thing a screen reader reads.
   */
  caption: string;
  /**
   * Visually hides the caption (it stays in the accessibility tree). Use
   * when a heading directly above already names the table.
   */
  captionHidden?: boolean;
  /**
   * Human name of a row, used as the accessible name of its selection
   * checkbox — "Select Ada Lovelace", never "Select". Defaults to `rowKey`,
   * which is better than nothing and worse than a name.
   */
  rowLabel?: (row: Row) => string;
  /** Current sort, or `null` for the server's natural order. */
  sort?: DataTableSort | null;
  /**
   * Receives the next sort on header activation (asc → desc → null).
   * Omitting it leaves every header inert, whatever the columns declare.
   */
  onSortChange?: (next: DataTableSort | null) => void;
  /**
   * Selected row keys — including keys that are not on the current page.
   * Those survive untouched through "select page".
   */
  selected?: readonly string[];
  /** Omitting it removes the selection column entirely. */
  onSelectionChange?: (next: string[]) => void;
  /** Tighter row height for long tables. */
  dense?: boolean;
  /** Paints `<Skeleton variant="data-table" />` instead of the table. */
  loading?: boolean;
  /**
   * Error message. Replaces the BODY only — the header and the pager stay
   * put, so the retry lands the reader back where they were.
   */
  error?: React.ReactNode;
  /** Renders a Retry button beside `error`. */
  onRetry?: () => void;
  /**
   * Shown in place of the body when `rows` is empty. Pass a different node
   * for "no matches, clear filters" than for "nothing here yet" — they are
   * different messages and only one of them is the reader's fault.
   */
  empty?: React.ReactNode;
  /** Wires the Pagination primitive under the table. */
  pagination?: DataTablePaginationState;
  /** Extra controls in the selection bar (bulk actions). */
  toolbar?: React.ReactNode;
}

export function DataTable<Row>({
  columns,
  rows,
  rowKey,
  caption,
  captionHidden = false,
  rowLabel,
  sort = null,
  onSortChange,
  selected = EMPTY_SELECTION,
  onSelectionChange,
  dense = false,
  loading = false,
  error,
  onRetry,
  empty,
  pagination,
  toolbar,
  className,
  ...props
}: DataTableProps<Row>) {
  const selectable = Boolean(onSelectionChange);
  const pageKeys = React.useMemo(() => rows.map(rowKey), [rows, rowKey]);
  const chosen = React.useMemo(() => new Set(selected), [selected]);

  // `rowHeader` on any column wins; otherwise the first column names the row.
  const headerColumnId =
    columns.find((column) => column.rowHeader)?.id ?? columns[0]?.id;

  const columnCount = columns.length + (selectable ? 1 : 0);
  const headState = pageSelectionState(pageKeys, selected);
  const cellPadding = dense ? 'px-3 py-1' : 'px-3 py-2';

  if (loading) {
    return (
      <div
        data-slot="data-table"
        data-min-viewport={String(MIN_VIEWPORT)}
        className={cn('flex w-full flex-col gap-3', className)}
        {...props}
      >
        <Skeleton variant="data-table" label={`Loading ${caption}`} />
      </div>
    );
  }

  return (
    <div
      data-slot="data-table"
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('flex w-full flex-col gap-3', className)}
      {...props}
    >
      {/* Rendered unconditionally, even while empty: a live region inserted
          in the same tick as its first message is usually dropped. */}
      <p role="status" aria-live="polite" className="sr-only">
        {selectionMessage(selected.length)}
      </p>

      {selectable && selected.length > 0 ? (
        <div
          data-slot="data-table-selection"
          className="flex flex-wrap items-center gap-3 rounded-md border border-border bg-muted px-3 py-2 text-sm"
        >
          <span className="text-muted-foreground">
            {selectionMessage(selected.length)}
          </span>
          {toolbar}
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="ms-auto"
            onClick={() => onSelectionChange!([])}
          >
            Clear selection
          </Button>
        </div>
      ) : null}

      {/*
        The scroll box is the table's own, and it is focusable + labelled:
        a region that scrolls but cannot be reached by keyboard is
        unreadable to anyone not using a mouse (axe: scrollable-region-
        focusable), and a sortless, selectionless table has no focusable
        descendant to inherit that from.
      */}
      <section
        data-slot="data-table-scroll"
        aria-label={caption}
        tabIndex={0}
        // `relative` is not styling — it is what makes this box the
        // containing block for the absolutely-positioned `sr-only` spans
        // inside the sort buttons. Without it those spans resolve against
        // the viewport, escape `overflow-x-auto` entirely, and their static
        // position in column 13 gives the PAGE a 233px horizontal scroll on
        // a 375px phone. The table scrolled correctly the whole time; the
        // thing dragging the page sideways was invisible text.
        className="relative w-full overflow-x-auto rounded-md border border-border focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring"
      >
        <table className="w-full border-collapse text-sm">
          <caption
            className={cn(
              // `text-start`, not `text-left`: in RTL the caption belongs on
              // the reading edge with the row headers it introduces.
              'px-3 py-2 text-start text-xs text-muted-foreground',
              captionHidden && 'sr-only',
            )}
          >
            {caption}
          </caption>
          <thead>
            <tr data-slot="data-table-head-row">
              {selectable ? (
                <th
                  scope="col"
                  data-slot="data-table-head"
                  className={cn(
                    'w-px border-b border-border text-start',
                    cellPadding,
                  )}
                >
                  {/* The flex wrapper is load-bearing, not decoration. Base
                      UI renders Checkbox.Root as a `<span>`, and a bare span
                      in a table cell computes `display: inline` — where
                      `size-4` is ignored outright and the 16px control paints
                      as a 2px sliver. Caught in a real browser; jsdom reports
                      every box as 0×0 and would have called it fine. */}
                  <span className="flex items-center">
                    <Checkbox
                      checked={headState === 'all'}
                      indeterminate={headState === 'some'}
                      aria-label={`Select all ${rows.length} rows on this page`}
                      data-slot="data-table-select-page"
                      onCheckedChange={() =>
                        onSelectionChange!(
                          togglePageSelection(selected, pageKeys),
                        )
                      }
                    />
                  </span>
                </th>
              ) : null}
              {columns.map((column) => {
                const sortable = Boolean(column.sortable && onSortChange);
                const name = columnName(column);
                return (
                  <th
                    key={column.id}
                    scope="col"
                    data-slot="data-table-head"
                    data-column={column.id}
                    aria-sort={
                      sortable ? ariaSortOf(sort, column.id) : undefined
                    }
                    className={cn(
                      'whitespace-nowrap border-b border-border text-xs font-medium uppercase tracking-wide text-muted-foreground',
                      column.align === 'end' ? 'text-end' : 'text-start',
                      // A sortable head's padding lives on the button, so the
                      // whole cell is the hit target rather than a word in the
                      // middle of it.
                      sortable ? 'p-0' : cellPadding,
                      column.className,
                    )}
                  >
                    {sortable ? (
                      <button
                        type="button"
                        data-slot="data-table-sort"
                        className={cn(
                          'flex w-full items-center gap-1 rounded-sm text-xs font-medium uppercase tracking-wide hover:text-foreground focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring',
                          cellPadding,
                          column.align === 'end' && 'justify-end',
                        )}
                        onClick={() => onSortChange!(nextSort(sort, column.id))}
                      >
                        {column.header}
                        <SortGlyph
                          direction={
                            sort?.columnId === column.id ? sort.direction : null
                          }
                        />
                        {/* `aria-sort` says where the column IS; nothing in
                            the platform says where a press takes it. */}
                        <span className="sr-only">
                          {sortActionLabel(sort, column.id, name)}
                        </span>
                      </button>
                    ) : (
                      column.header
                    )}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {error !== null && error !== undefined ? (
              <tr data-slot="data-table-message">
                <td colSpan={columnCount} className="px-3 py-8 text-center">
                  <div
                    role="alert"
                    className="flex flex-col items-center gap-2 text-sm text-destructive"
                  >
                    {error}
                    {onRetry ? (
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={onRetry}
                      >
                        Retry
                      </Button>
                    ) : null}
                  </div>
                </td>
              </tr>
            ) : rows.length === 0 ? (
              <tr data-slot="data-table-message">
                <td
                  colSpan={columnCount}
                  className="px-3 py-8 text-center text-sm text-muted-foreground"
                >
                  {empty ?? 'No results.'}
                </td>
              </tr>
            ) : (
              rows.map((row) => {
                const key = rowKey(row);
                const isSelected = chosen.has(key);
                return (
                  <tr
                    key={key}
                    data-slot="data-table-row"
                    data-selected={isSelected || undefined}
                    aria-selected={selectable ? isSelected : undefined}
                    className={cn(
                      'border-b border-border last:border-b-0',
                      isSelected
                        ? 'bg-accent text-accent-foreground'
                        : 'hover:bg-muted',
                    )}
                  >
                    {selectable ? (
                      <td className={cn('w-px', cellPadding)}>
                        {/* See the head cell: the flex wrapper is what gives
                            the Base UI span a block formatting context. */}
                        <span className="flex items-center">
                          <Checkbox
                            checked={isSelected}
                            // Names the ROW, not the control. "Select" ×20 is
                            // a list of identical controls with no way to
                            // tell which row you are about to act on.
                            aria-label={`Select ${rowLabel ? rowLabel(row) : key}`}
                            data-slot="data-table-select-row"
                            onCheckedChange={() =>
                              onSelectionChange!(toggleKey(selected, key))
                            }
                          />
                        </span>
                      </td>
                    ) : null}
                    {columns.map((column) =>
                      column.id === headerColumnId ? (
                        <th
                          key={column.id}
                          scope="row"
                          data-slot="data-table-row-header"
                          className={cn(
                            'whitespace-nowrap text-start font-normal',
                            cellPadding,
                            column.className,
                          )}
                        >
                          {column.cell(row)}
                        </th>
                      ) : (
                        <td
                          key={column.id}
                          className={cn(
                            cellPadding,
                            column.align === 'end'
                              ? 'text-end tabular-nums'
                              : 'text-start',
                            column.className,
                          )}
                        >
                          {column.cell(row)}
                        </td>
                      ),
                    )}
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </section>

      {pagination ? <DataTablePager {...pagination} /> : null}
    </div>
  );
}

function SortGlyph({ direction }: { direction: 'asc' | 'desc' | null }) {
  // Direction is never colour-only: the glyph changes shape, and `aria-sort`
  // carries it for anyone not looking.
  const Icon =
    direction === 'asc'
      ? ArrowUpIcon
      : direction === 'desc'
        ? ArrowDownIcon
        : ChevronsUpDownIcon;
  return (
    <Icon
      aria-hidden
      data-slot="data-table-sort-glyph"
      data-direction={direction ?? 'none'}
      className={cn('size-3.5 shrink-0', direction === null && 'opacity-50')}
    />
  );
}

/**
 * The pager, wired to the Pagination primitive.
 *
 * Page-based, never infinite scroll (PAGINATION_PHILOSOPHY /
 * DATA_TABLE_PHILOSOPHY §4): page 3 has to be a place you can return to.
 * Every control is a real `<a href>`; `onPageChange` only intercepts the
 * click so a client router can take it.
 */
function DataTablePager({
  page,
  pageCount,
  href,
  onPageChange,
}: DataTablePaginationState) {
  const current = clampPage(page, pageCount);
  const hrefFor = (target: number) =>
    href?.(clampPage(target, pageCount)) ?? '#';

  const go = (target: number) => (event: React.MouseEvent<HTMLAnchorElement>) => {
    const clamped = clampPage(target, pageCount);
    if (clamped === current && target !== current) {
      // Prev on page 1 / Next on the last page: the control is
      // `aria-disabled`, so it must also not navigate.
      event.preventDefault();
      return;
    }
    if (!onPageChange) return;
    event.preventDefault();
    onPageChange(clamped);
  };

  return (
    <Pagination>
      {/* gap-2, not the primitive's gap-1: `size-9` targets plus an 8px
          boundary gap keep axe's target-spacing math clear (WCAG 2.2 2.5.8). */}
      <PaginationContent className="gap-2">
        <PaginationItem>
          <PaginationPrevious
            href={hrefFor(current - 1)}
            onClick={go(current - 1)}
            aria-disabled={current === 1 || undefined}
          />
        </PaginationItem>
        {pageWindow(current, pageCount).map((value, index) =>
          value === null ? (
            <PaginationItem key={`gap-${index}`}>
              <PaginationEllipsis />
            </PaginationItem>
          ) : (
            <PaginationItem key={value}>
              <PaginationLink
                href={hrefFor(value)}
                active={value === current}
                onClick={go(value)}
              >
                {value}
              </PaginationLink>
            </PaginationItem>
          ),
        )}
        <PaginationItem>
          <PaginationNext
            href={hrefFor(current + 1)}
            onClick={go(current + 1)}
            aria-disabled={current === pageCount || undefined}
          />
        </PaginationItem>
      </PaginationContent>
    </Pagination>
  );
}

export {
  ariaSortOf,
  clampPage,
  columnName,
  compareValues,
  nextSort,
  pageSelectionState,
  pageWindow,
  selectionMessage,
  sortActionLabel,
  sortRows,
  toggleKey,
  togglePageSelection,
} from '@/components/ui/patterns/data-table-model';
export type {
  DataTableSort,
  PageSelectionState,
  SortDirection,
  SortValue,
} from '@/components/ui/patterns/data-table-model';

export type SortDirection = 'asc' | 'desc';

/**
 * The whole sort state of a table: one column, one direction.
 *
 * Multi-column sort is deliberately not modelled — see the note on
 * `nextSort`.
 */
export interface DataTableSort {
  /**
   * The column's `id`. This is the SORT KEY, not the display name — it is
   * what goes into `?sort=` and what a server-side query orders by, so it has
   * to survive a column being relabelled.
   */
  columnId: string;
  direction: SortDirection;
}

/**
 * Values a column can sort by. `sortRows` compares these; anything richer
 * (a struct, a locale-sensitive collation) is the caller's job to reduce to
 * one of these first.
 */
export type SortValue = string | number | boolean | Date | null | undefined;

/**
 * The sort a header click should produce, given what is sorted now.
 *
 * The cycle is **asc → desc → unsorted**, and clicking a different column
 * always starts that column at ascending rather than inheriting the previous
 * column's direction (inheriting reads as "the table re-sorted itself
 * backwards", which is exactly the surprise a table should not produce).
 *
 * The third state is the reason this is a function and not `!direction`.
 * Dropping back to unsorted is what returns the reader to the server's
 * natural order — usually "newest first", usually the order they wanted —
 * and a two-state toggle makes that order unreachable without a page reload.
 *
 * Multi-column sort (shift-click, `?sort=a,b&dir=asc,desc`) is described by
 * DATA_TABLE_PHILOSOPHY §2 as opt-in. It is not implemented: a second sort
 * key changes the URL contract, the header UI and the comparator all at once,
 * and shipping half of it would put a shift-click affordance on a table that
 * silently ignores it.
 */
export function nextSort(
  current: DataTableSort | null | undefined,
  columnId: string,
): DataTableSort | null {
  if (!current || current.columnId !== columnId) {
    return { columnId, direction: 'asc' };
  }
  if (current.direction === 'asc') return { columnId, direction: 'desc' };
  return null;
}

/**
 * The `aria-sort` value for a column header.
 *
 * Every sortable column gets one — `'none'` on the inactive ones — because
 * the attribute is also how a screen reader knows the column is sortable at
 * all. Non-sortable columns pass `undefined` and render no attribute.
 */
export function ariaSortOf(
  current: DataTableSort | null | undefined,
  columnId: string,
): 'ascending' | 'descending' | 'none' {
  if (!current || current.columnId !== columnId) return 'none';
  return current.direction === 'asc' ? 'ascending' : 'descending';
}

/**
 * What activating this header will do next, as a sentence.
 *
 * Rendered `sr-only` inside the sort button. `aria-sort` announces the state
 * the column is IN; nothing in the platform announces the state a press will
 * move it TO, and a control whose effect is unannounced is a control you have
 * to click to discover.
 */
export function sortActionLabel(
  current: DataTableSort | null | undefined,
  columnId: string,
  columnName: string,
): string {
  const next = nextSort(current, columnId);
  if (next === null) return `Remove sorting from ${columnName}`;
  return `Sort by ${columnName}, ${next.direction === 'asc' ? 'ascending' : 'descending'}`;
}

/**
 * Sort rows locally.
 *
 * The table never calls this — it renders `rows` in the order it was given,
 * because at any real scale the sort belongs to the query that fetched them
 * (DATA_TABLE_PHILOSOPHY §10: client-only sort above ~1,000 rows is
 * forbidden). It is exported for the small-table case, where the caller holds
 * the whole array in memory and would otherwise write this by hand — badly:
 * `Array#sort` is comparison-based, so the naive `a - b` on mixed
 * null/string/number data throws or produces an order that changes between
 * runs.
 *
 * Stable: equal values keep their input order, via an index tiebreak.
 * `null` / `undefined` sort last in BOTH directions — a missing value is not
 * "small", and flipping the direction should not march the blanks to the top.
 */
export function sortRows<Row>(
  rows: readonly Row[],
  sort: DataTableSort | null | undefined,
  getValue: (row: Row, columnId: string) => SortValue,
): Row[] {
  if (!sort) return [...rows];
  const sign = sort.direction === 'asc' ? 1 : -1;
  return rows
    .map((row, index) => ({ row, index }))
    .sort((a, b) => {
      const left = getValue(a.row, sort.columnId);
      const right = getValue(b.row, sort.columnId);
      const leftBlank = left === null || left === undefined;
      const rightBlank = right === null || right === undefined;
      // Resolved BEFORE `sign` is applied: a missing value is not "small",
      // and reversing the sort should not march every blank to the top.
      if (leftBlank !== rightBlank) return leftBlank ? 1 : -1;
      const delta = compareValues(left, right);
      return delta !== 0 ? delta * sign : a.index - b.index;
    })
    .map((entry) => entry.row);
}

/**
 * Ascending comparison across the `SortValue` union.
 *
 * Blanks last (returned unsigned so `sortRows` does not flip them), numbers
 * and dates numerically, everything else through `localeCompare` with
 * `numeric` so `item-2` precedes `item-10`.
 */
export function compareValues(a: SortValue, b: SortValue): number {
  const aBlank = a === null || a === undefined;
  const bBlank = b === null || b === undefined;
  if (aBlank && bBlank) return 0;
  // Not multiplied by `sign` in sortRows — see the note there.
  if (aBlank) return 1;
  if (bBlank) return -1;

  const left = a instanceof Date ? a.getTime() : a;
  const right = b instanceof Date ? b.getTime() : b;

  if (typeof left === 'number' && typeof right === 'number') {
    return left === right ? 0 : left < right ? -1 : 1;
  }
  if (typeof left === 'boolean' || typeof right === 'boolean') {
    return Number(left) - Number(right);
  }
  return String(left).localeCompare(String(right), undefined, {
    numeric: true,
    sensitivity: 'base',
  });
}

/** Header-checkbox state for the rows currently on screen. */
export type PageSelectionState = 'none' | 'some' | 'all';

/**
 * How much of the current page is selected.
 *
 * `'some'` drives the checkbox's indeterminate state. An empty page is
 * `'none'`, never `'all'` — `every()` over an empty array is `true`, which is
 * how a header checkbox on an empty table ends up rendering as checked.
 */
export function pageSelectionState(
  pageKeys: readonly string[],
  selected: readonly string[],
): PageSelectionState {
  if (pageKeys.length === 0) return 'none';
  const chosen = new Set(selected);
  let hits = 0;
  for (const key of pageKeys) if (chosen.has(key)) hits += 1;
  if (hits === 0) return 'none';
  return hits === pageKeys.length ? 'all' : 'some';
}

/**
 * Add or remove one row key, preserving order of the rest.
 *
 * Keyed by row ID, never by index — DATA_TABLE_PHILOSOPHY §5's selection
 * test is exactly the index-keyed bug: sort or paginate and index 3 is a
 * different row, so the checkmarks stay put while the selection underneath
 * them silently changes rows.
 */
export function toggleKey(
  selected: readonly string[],
  key: string,
): string[] {
  return selected.includes(key)
    ? selected.filter((entry) => entry !== key)
    : [...selected, key];
}

/**
 * Select or clear every row on the current page, leaving selections made on
 * OTHER pages untouched.
 *
 * That last clause is the whole point. "Select page" that replaces the
 * selection array is how selections vanish when the reader pages back — the
 * failure DATA_TABLE_PHILOSOPHY §5 names, and the one nobody notices until a
 * bulk action runs on a third of the rows they thought they had picked.
 *
 * Partial (`'some'`) promotes to all, matching the checkbox's own
 * indeterminate → checked semantics.
 */
export function togglePageSelection(
  selected: readonly string[],
  pageKeys: readonly string[],
): string[] {
  const state = pageSelectionState(pageKeys, selected);
  if (state === 'all') {
    const onPage = new Set(pageKeys);
    return selected.filter((key) => !onPage.has(key));
  }
  const chosen = new Set(selected);
  return [...selected, ...pageKeys.filter((key) => !chosen.has(key))];
}

/**
 * The live-region sentence for the current selection.
 *
 * Empty string when nothing is selected, so the region can be rendered
 * unconditionally: an `aria-live` element that only appears once there is
 * something to say is inserted and announced in the same tick, which most
 * screen readers drop.
 *
 * Deliberately no "of N": the selection spans pages and the page only knows
 * its own row count, so "1 of 3 rows selected" over a 3-row page reads as
 * "one of these three" when the selected row may be two pages away. A bare
 * count is the only number the table can honestly report.
 */
export function selectionMessage(count: number): string {
  if (count <= 0) return '';
  return `${count} ${count === 1 ? 'row' : 'rows'} selected`;
}

/**
 * The page numbers a pager should render, with `null` for each elided run.
 *
 * First and last are always present (they are the two destinations a reader
 * actually aims for), plus `siblings` pages either side of the current one.
 * A gap of exactly one page is filled rather than eliding it — `1 … 3` and
 * `1 2 3` cost the same width, and the ellipsis is a lie about how much was
 * hidden.
 */
export function pageWindow(
  page: number,
  pageCount: number,
  siblings = 1,
): (number | null)[] {
  if (pageCount <= 0) return [];
  const current = clampPage(page, pageCount);
  const shown = new Set<number>([1, pageCount]);
  for (let offset = -siblings; offset <= siblings; offset += 1) {
    const candidate = current + offset;
    if (candidate >= 1 && candidate <= pageCount) shown.add(candidate);
  }

  const out: (number | null)[] = [];
  let previous = 0;
  for (const value of [...shown].sort((a, b) => a - b)) {
    // A gap of exactly one page is filled, not elided: `1 … 3` and `1 2 3`
    // cost the same width, and the ellipsis claims more was hidden than was.
    if (value - previous === 2 && previous !== 0) out.push(previous + 1);
    else if (value - previous > 1) out.push(null);
    out.push(value);
    previous = value;
  }
  return out;
}

/** Keep a page number inside `1..pageCount`. */
export function clampPage(page: number, pageCount: number): number {
  if (!Number.isFinite(page)) return 1;
  return Math.min(Math.max(Math.trunc(page), 1), Math.max(pageCount, 1));
}

/**
 * The plain-text name of a column, for the strings assistive tech reads.
 *
 * A column header is a `ReactNode` — it can be an icon, a badge, a wrapped
 * two-line label — and none of that can be concatenated into "Sort by …".
 * `name` is the escape hatch; a string header is used as-is; the `id` is the
 * last resort, and it is at least a word the caller chose.
 */
export function columnName(column: {
  id: string;
  header?: unknown;
  name?: string;
}): string {
  if (column.name) return column.name;
  return typeof column.header === 'string' ? column.header : column.id;
}

/**
 * @interlace/ui — DataTable, the parts with no JSX in them.
 *
 * Every decision a data table makes that is arithmetic rather than markup
 * lives here: what the next sort is, which rows a header checkbox owns, what
 * `aria-sort` should say, which page numbers the pager renders.
 *
 * ## Why a separate module
 *
 * These are the only parts of a table that can be *wrong* in a way a
 * screenshot will not show. A sort cycle that skips a state, a "select page"
 * checkbox that quietly drops the selections made on page 1, an ellipsis
 * window that renders `1 … 2` — each is a pure function of its inputs and
 * each shipped, historically, buried in a JSX callback where no test could
 * reach it. Anything below is exercised directly by
 * `__tests__/data-table-model.test.ts`; `data-table.tsx` holds no branch that
 * is not a render decision.
 *
 * Nothing here imports React. The module is safe on a server, in a worker, or
 * in a consumer's own URL-state layer — which matters, because the table
 * itself owns no state (see `data-table.tsx`) and the caller has to compute
 * exactly these values when it wires sort and selection to the query string.
 */

